declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/health_network_v590.php';$u=current_user();if(!$u){header('Location: /login.php?redirect='.urlencode($_SERVER['REQUEST_URI']??'/health-network-account.php'));exit;}$id=(int)($_GET['id']??0);try{$q=db()->prepare('SELECT r.*,b.user_id,b.lab_id FROM health_lab_reports_v590 r JOIN health_lab_bookings_v590 b ON b.id=r.booking_id WHERE r.id=? AND r.tenant_id=? AND r.status=\'published\' LIMIT 1');$q->execute([$id,hn590_tid()]);$r=$q->fetch();if(!$r)throw new RuntimeException('Report not found.');$allowed=(int)$r['user_id']===(int)$u['id']||(function_exists('has_permission')&&has_permission('healthnet.reports.manage',$u)&&hn590_scope_allows('lab',(int)$r['lab_id'],$u));if(function_exists('is_super_admin')&&is_super_admin($u))$allowed=true;if(!$allowed){http_response_code(403);exit('Report access denied.');}if(!empty($r['report_file'])){$name=basename((string)$r['report_file']);$path=__DIR__.'/storage/health-reports/'.$name;if(!is_file($path))throw new RuntimeException('Report file is unavailable.');$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$mime=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'][$ext]??'application/octet-stream';header('Content-Type: '.$mime);header('Content-Disposition: inline; filename="health-report.'.$ext.'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;}header('Content-Type: text/html; charset=utf-8');echo '<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lab Report</title><style>body{font:16px system-ui;background:#f4f7fb;color:#172033;padding:30px}.box{max-width:760px;margin:auto;background:#fff;padding:28px;border-radius:18px;border:1px solid #e3eaf2;white-space:pre-wrap}</style><div class="box">'.e((string)($r['report_text']??'Report note unavailable.')).'</div>';exit;}catch(Throwable $e){http_response_code(404);exit(e($e->getMessage()));}
